        (PerfectFunctionalRepresentations.Incidence.PartitionConstruction.pps.{u}
          (PerfectFunctionalRepresentations.Incidence.partitionConstruction.{u} D w hw))))
    (HSub.hSub.{0, 0, 0}
      (Fintype.card.{u} (PerfectFunctionalRepresentations.Incidence.PositivePartition.{u} D w)) 1)

∀ {α : Type u} [inst : Fintype.{u} α] [inst_1 : Nonempty.{u + 1} α]
  (D : PerfectFunctionalRepresentations.CompressedPatternData.{u} α)
  (w : PerfectFunctionalRepresentations.Incidence.AdmissiblePartition.{u} D → ℝ)
  (hw : PerfectFunctionalRepresentations.Incidence.Feasible.{u} D w),
  Eq.{1}
    (PerfectFunctionalRepresentations.MatrixOperations.OperationPath.length.{u}
      (PerfectFunctionalRepresentations.MatrixOperations.LabelledOperationResult.path.{u, u}
        (PerfectFunctionalRepresentations.Incidence.PartitionConstruction.ppm.{u}
          (PerfectFunctionalRepresentations.Incidence.partitionConstruction.{u} D w hw))))
    (HSub.hSub.{0, 0, 0} (Fintype.card.{u} (PerfectFunctionalRepresentations.Incidence.PositiveBlock.{u} D w))
      (Fintype.card.{u} (PerfectFunctionalRepresentations.Incidence.OccurringPattern.{u} D)))

∀ {α : Type u} [inst : Fintype.{u} α] [inst_1 : Nonempty.{u + 1} α]
  {D : PerfectFunctionalRepresentations.CompressedPatternData.{u} α}
  {w : PerfectFunctionalRepresentations.Incidence.AdmissiblePartition.{u} D → ℝ}
  (C : PerfectFunctionalRepresentations.Incidence.PartitionConstruction.{u} D w),
  PerfectFunctionalRepresentations.IsPerfectlyRepresentableChannel.{u, u}
    (PerfectFunctionalRepresentations.CompressedPatternData.channel.{u} D)

∀ {α : Type u} [inst : Fintype.{u} α] [inst_1 : Nonempty.{u + 1} α]
  (D : PerfectFunctionalRepresentations.CompressedPatternData.{u} α) {m : ℕ}
  (e : Equiv.{u + 1, 1} (PerfectFunctionalRepresentations.Incidence.OccurringPattern.{u} D) (Fin m)),
  (∃ w, PerfectFunctionalRepresentations.Incidence.Feasible.{u} D w) ↔
    PerfectFunctionalRepresentations.MatrixOperations.FromAllOnes.{u}
      (PerfectFunctionalRepresentations.CompressedPatternData.toActiveFiniteChannel.{u} D e)

∀ {α : Type u} [inst : Fintype.{u} α] [inst_1 : Nonempty.{u + 1} α]
  (D : PerfectFunctionalRepresentations.CompressedPatternData.{u} α) {m : ℕ}
  (e : Equiv.{u + 1, 1} (PerfectFunctionalRepresentations.Incidence.OccurringPattern.{u} D) (Fin m)),
  (∃ w, PerfectFunctionalRepresentations.Incidence.Feasible.{u} D w) ↔
    PerfectFunctionalRepresentations.MatrixOperations.ToAllOnes.{u}
      (PerfectFunctionalRepresentations.CompressedPatternData.toActiveFiniteChannel.{u} D e)

∀ {α : Type u} [inst : Fintype.{u} α] [inst_1 : Nonempty.{u + 1} α] {β : Type v} [inst_2 : Finite.{v + 1} β]
  (κ : α → PMF.{v} β) (hκ : PerfectFunctionalRepresentations.IsSingularChannel.{u, v} κ),
  PerfectFunctionalRepresentations.IsPerfectlyRepresentableChannel.{u, v} κ ↔
    ∃ x,
      PerfectFunctionalRepresentations.Primal.Feasible.{u}
          (PerfectFunctionalRepresentations.compressedPatternData.{u, v} κ hκ) x ∧
        Eq.{1}
          (PerfectFunctionalRepresentations.Primal.objective.{u}
            (PerfectFunctionalRepresentations.compressedPatternData.{u, v} κ hκ) x)
          1

∀ {beta : Type u} [inst : Fintype.{u} beta] (p q : PMF.{u} beta),
  Eq.{1}
    (PerfectFunctionalRepresentations.mismatchMass.{u}
      (PerfectFunctionalRepresentations.maximalCoupling.{u} p q))
    (HSub.hSub.{0, 0, 0} 1 (PerfectFunctionalRepresentations.overlapMass.{u} p q))

∀ {beta : Type u} [inst : Fintype.{u} beta] (p q : PMF.{u} beta),
  Eq.{1}
    (PerfectFunctionalRepresentations.mismatchMass.{u}
        (PerfectFunctionalRepresentations.maximalCoupling.{u} p q)).toReal
    (PerfectFunctionalRepresentations.finiteTV.{u} p q)

∀ {beta : Type u} [inst : Fintype.{u} beta] (p q : PMF.{u} beta),
  Eq.{1}
    (LeanInfoTheory.Shannon.decodingErrorProbability.{u, u}
      (PerfectFunctionalRepresentations.maximalCoupling.{u} p q) id.{u + 1})
    (PerfectFunctionalRepresentations.finiteTV.{u} p q)

∀ {beta : Type u} [inst : Fintype.{u} beta] (p : PMF.{0} (Fin 2)) (q : PMF.{u} (Fin 2 → beta))
  (w : Fin 2 → beta) (hw : Ne.{1} (q w) 0),
  Eq.{u + 1}
    (LeanInfoTheory.Shannon.condFstGivenSnd.{u, u}
      (LeanInfoTheory.Shannon.sndThirdMarginal.{0, u, u}
        (PerfectFunctionalRepresentations.canonicalJoint.{0, u} p q))
      w
      (Eq.mpr.{0}
        (id.{0}
          (congrFun'.{1, 1}
            (congrArg.{1, 1} Ne.{1}
              (congrFun'.{u + 1, 1}
                (congrArg.{u + 1, u + 1} DFunLike.coe.{u + 1, u + 1, 1}
                  (Eq.trans.{u + 1}
                    (LeanInfoTheory.Shannon.sndMarginal_sndThirdMarginal.{0, u, u}
                      (PerfectFunctionalRepresentations.canonicalJoint.{0, u} p q))
                    (PerfectFunctionalRepresentations.thirdMarginal_canonicalJoint.{0, u} p q)))
                w))
            0))
        hw))
    (PMF.map.{0, u} w p)

∀ {beta : Type u} [inst : Fintype.{u} beta] (p : PMF.{0} (Fin 2)) (q : PMF.{u} (Fin 2 → beta)),
  Eq.{1}
    (LeanInfoTheory.Shannon.condEntropyOf.{u, u, u}
      (PerfectFunctionalRepresentations.canonicalJoint.{0, u} p q) (fun t => t.2.1) fun t => t.2.2)
    (HMul.hMul.{0, 0, 0}
      (PerfectFunctionalRepresentations.mismatchMass.{u}
          (PMF.map.{u, u} (⇑(finTwoArrowEquiv.{u} beta)) q)).toReal
      (LeanInfoTheory.Shannon.entropy.{0} p))

∀ {beta : Type u} [inst : Fintype.{u} beta] (p : PMF.{0} (Fin 2)) (q : PMF.{u} (Fin 2 → beta)),
  Eq.{1}
    (LeanInfoTheory.Shannon.mutualInfoOf.{u, u, u}
      (PerfectFunctionalRepresentations.canonicalJoint.{0, u} p q) (fun t => t.2.1) fun t => t.2.2)
    (HSub.hSub.{0, 0, 0}
      (LeanInfoTheory.Shannon.entropyOf.{u, u} (PerfectFunctionalRepresentations.canonicalJoint.{0, u} p q)
        fun t => t.2.1)
      (HMul.hMul.{0, 0, 0}
        (PerfectFunctionalRepresentations.mismatchMass.{u}
            (PMF.map.{u, u} (⇑(finTwoArrowEquiv.{u} beta)) q)).toReal
        (LeanInfoTheory.Shannon.entropy.{0} p)))

∀ {beta : Type u} [inst : Fintype.{u} beta] {omega : Type v} {mu : PMF.{v} omega} {X : omega → Fin 2}
  {Y : omega → beta} {W : omega → Fin 2 → beta},
  PerfectFunctionalRepresentations.IsCanonicalFunctionalRepresentationOf.{v, 0, u} mu X Y W →
    Eq.{1} (LeanInfoTheory.Shannon.condEntropyOf.{v, u, u} mu Y W)
      (HMul.hMul.{0, 0, 0}
        (PerfectFunctionalRepresentations.mismatchMass.{u}
            (PMF.map.{u, u} (⇑(finTwoArrowEquiv.{u} beta)) (PMF.map.{v, u} W mu))).toReal
        (LeanInfoTheory.Shannon.entropyOf.{v, 0} mu X))

∀ {beta : Type u} [inst : Fintype.{u} beta] {omega : Type v} {mu : PMF.{v} omega} {X : omega → Fin 2}
  {Y : omega → beta} {W : omega → Fin 2 → beta},
  PerfectFunctionalRepresentations.IsCanonicalFunctionalRepresentationOf.{v, 0, u} mu X Y W →
    Eq.{1} (LeanInfoTheory.Shannon.mutualInfoOf.{v, u, u} mu Y W)
      (HSub.hSub.{0, 0, 0} (LeanInfoTheory.Shannon.entropyOf.{v, u} mu Y)
        (HMul.hMul.{0, 0, 0}
          (PerfectFunctionalRepresentations.mismatchMass.{u}
              (PMF.map.{u, u} (⇑(finTwoArrowEquiv.{u} beta)) (PMF.map.{v, u} W mu))).toReal
          (LeanInfoTheory.Shannon.entropyOf.{v, 0} mu X)))

∀ {omega : Type u} {omega' : Type v} {alpha : Type w} {beta : Type x} {p : PMF.{u} omega}
  {p' : PMF.{v} omega'} {X : omega → alpha} {Y : omega → beta} {W : omega → alpha → beta}
  {X' : omega' → alpha} {Y' : omega' → beta} {W' : omega' → alpha → beta},
  Eq.{max (w + 1) (x + 1)}
      (PMF.map.{u, max w x} (fun s => Prod.mk.{w, max w x} (X s) (Prod.mk.{x, max w x} (Y s) (W s))) p)
      (PMF.map.{v, max w x} (fun s => Prod.mk.{w, max w x} (X' s) (Prod.mk.{x, max w x} (Y' s) (W' s))) p') →
    (PerfectFunctionalRepresentations.IsCanonicalFunctionalRepresentationOf.{u, w, x} p X Y W ↔
      PerfectFunctionalRepresentations.IsCanonicalFunctionalRepresentationOf.{v, w, x} p' X' Y' W')

∀ {alpha : Type u} {beta : Type v} (p : PMF.{u} alpha) (q : PMF.{max u v} (alpha → beta)),
  Eq.{u + 1}
    (LeanInfoTheory.Shannon.fstMarginal.{u, max v u}
      (PerfectFunctionalRepresentations.canonicalJoint.{u, v} p q))
    p

∀ {alpha : Type u} {beta : Type v} (p : PMF.{u} alpha) (q : PMF.{max u v} (alpha → beta)),
  Eq.{max (u + 1) (v + 1)}
    (LeanInfoTheory.Shannon.thirdMarginal.{u, v, max v u}
      (PerfectFunctionalRepresentations.canonicalJoint.{u, v} p q))
    q

∀ {alpha : Type u} {beta : Type v} (p : PMF.{u} alpha) (q : PMF.{max u v} (alpha → beta)),
  Eq.{max (u + 1) (v + 1)}
    (LeanInfoTheory.Shannon.fstThirdMarginal.{u, v, max v u}
      (PerfectFunctionalRepresentations.canonicalJoint.{u, v} p q))
    (LeanInfoTheory.Shannon.indepProd.{u, max u v} p q)

∀ {alpha : Type u} {beta : Type v} (p : PMF.{u} alpha) (q : PMF.{max u v} (alpha → beta)),
  PerfectFunctionalRepresentations.IsCanonicalFunctionalRepresentation.{u, v}
    (PerfectFunctionalRepresentations.canonicalJoint.{u, v} p q)

∀ {alpha : Type u} {beta : Type v} (p : PMF.{u} alpha) (q : PMF.{max u v} (alpha → beta)),
  Eq.{max (u + 1) (v + 1)}
    (LeanInfoTheory.Shannon.fstSndMarginal.{u, v, max v u}
      (PerfectFunctionalRepresentations.canonicalJoint.{u, v} p q))
    (PMF.channelJoint.{u, v} p fun a => PMF.map.{max u v, v} (fun f => f a) q)

∀ {omega : Type u} {alpha : Type v} {beta : Type w} {mu : PMF.{u} omega} {X : omega → alpha}
  {Y : omega → beta} {W : omega → alpha → beta},
  PerfectFunctionalRepresentations.IsCanonicalFunctionalRepresentationOf.{u, v, w} mu X Y W →
    Eq.{max (v + 1) (w + 1)}
      (LeanInfoTheory.Shannon.fstSndMarginal.{v, w, max w v}
        (PerfectFunctionalRepresentations.canonicalJoint.{v, w} (PMF.map.{u, v} X mu)
          (PMF.map.{u, max v w} W mu)))
      (PMF.map.{u, max w v} (fun s => Prod.mk.{v, w} (X s) (Y s)) mu)

∀ {alpha : Type u} {beta : Type v} [inst : Fintype.{u} alpha] [inst_1 : Fintype.{v} beta]
  [inst_2 : Fintype.{max u v} (alpha → beta)] (pXY : PMF.{max v u} (Prod.{u, v} alpha beta)),
  PerfectFunctionalRepresentations.IsPerfectlyRepresentablePair.{u, v} pXY ↔
    ∃ q,
      Eq.{max (u + 1) (v + 1)}
          (LeanInfoTheory.Shannon.fstSndMarginal.{u, v, max v u}
            (PerfectFunctionalRepresentations.canonicalJoint.{u, v}
              (LeanInfoTheory.Shannon.fstMarginal.{u, v} pXY) q))
          pXY ∧
        PerfectFunctionalRepresentations.IsPerfectFunctionalRepresentation.{u, v, max v u}
          (PerfectFunctionalRepresentations.canonicalJoint.{u, v}
            (LeanInfoTheory.Shannon.fstMarginal.{u, v} pXY) q)

∀ {alpha : Type u} {beta : Type v} [inst : Fintype.{u} alpha] [inst_1 : Fintype.{v} beta]
  [inst_2 : Fintype.{max u v} (alpha → beta)] (p : PMF.{u} alpha) (q : PMF.{max u v} (alpha → beta)),
  PerfectFunctionalRepresentations.IsPerfectFunctionalRepresentation.{u, v, max v u}
      (PerfectFunctionalRepresentations.canonicalJoint.{u, v} p q) ↔
    LeanInfoTheory.Shannon.IsMarkovChain.{u, v, max v u}
      (PerfectFunctionalRepresentations.canonicalJoint.{u, v} p q)

declarations.documentation:
Transfer the all-prior consequence to a specified source through C01's
pair-law transport. The existential witness may live on an enlarged space;
the original source type remains unrestricted.

declarations.type:
∀ {omega : Type u} {omega' : Type v} {alpha : Type w} {beta : Type x} {gamma : Type y} {p : PMF.{u} omega}
  {p' : PMF.{v} omega'} {X : omega → alpha} {Y : omega → beta} {Z : omega → gamma} {X' : omega' → alpha}
  {Y' : omega' → beta} {Z' : omega' → gamma},
  Eq.{max (max (w + 1) (x + 1)) (y + 1)}
      (PMF.map.{u, max (max y x) w}
        (fun omega => Prod.mk.{w, max y x} (X omega) (Prod.mk.{x, y} (Y omega) (Z omega))) p)
      (PMF.map.{v, max (max y x) w}
        (fun omega => Prod.mk.{w, max y x} (X' omega) (Prod.mk.{x, y} (Y' omega) (Z' omega))) p') →
    (PerfectFunctionalRepresentations.IsFunctionalRepresentationOf.{u, w, x, y} p X Y Z ↔
      PerfectFunctionalRepresentations.IsFunctionalRepresentationOf.{v, w, x, y} p' X' Y' Z')

∀ {omega : Type u} {omega' : Type v} {alpha : Type w} {beta : Type x} {gamma : Type y}
  [inst : Fintype.{w} alpha] [inst_1 : Fintype.{x} beta] [inst_2 : Fintype.{y} gamma] {p : PMF.{u} omega}
  {p' : PMF.{v} omega'} {X : omega → alpha} {Y : omega → beta} {Z : omega → gamma} {X' : omega' → alpha}
  {Y' : omega' → beta} {Z' : omega' → gamma},
  Eq.{max (max (w + 1) (x + 1)) (y + 1)}
      (PMF.map.{u, max (max y x) w}
        (fun omega => Prod.mk.{w, max y x} (X omega) (Prod.mk.{x, y} (Y omega) (Z omega))) p)
      (PMF.map.{v, max (max y x) w}
        (fun omega => Prod.mk.{w, max y x} (X' omega) (Prod.mk.{x, y} (Y' omega) (Z' omega))) p') →
    (PerfectFunctionalRepresentations.IsPerfectFunctionalRepresentationOf.{u, w, x, y} p X Y Z ↔
      PerfectFunctionalRepresentations.IsPerfectFunctionalRepresentationOf.{v, w, x, y} p' X' Y' Z')

∀ {alpha : Type u} {beta : Type v} (kappa : alpha → PMF.{v} beta) (x : alpha),
  Eq.{v + 1}
    (PMF.map.{v, v} Subtype.val.{v + 1}
      (PerfectFunctionalRepresentations.restrictActiveOutputs.{u, v} kappa x))
    (kappa x)

∀ {alpha : Type u} {beta : Type v} (kappa : alpha → PMF.{v} beta),
  Eq.{v + 1}
    (PerfectFunctionalRepresentations.activeOutputs.{u, v}
      (PerfectFunctionalRepresentations.restrictActiveOutputs.{u, v} kappa))
    Set.univ.{v}

declarations.documentation:
Singularity is equivalent to perfect representability when the union of all
row supports contains at most two outputs. The active subtype's enumeration is internal;
globally unused ambient outputs impose no additional hypothesis.
